 /// The ring's loop's pass (`ring_worker`'s `TICK_US`).
 const PASS: Duration = Duration::from_millis(2);

+// Scratch-only observation: bounded records, no formatting or allocation in push.
+const PHASE_RECORDS: usize = 65_536;
+const NO_CALL: u8 = u8::MAX;
+
+#[derive(Clone, Copy, Debug)]
+enum Phase {
+    ThereEnter,
+    ThereExit,
+    ShownEnter,
+    ShownExit,
+    AskEnter,
+    AskExit,
+    CoveredEnter,
+    CoveredExit,
+    TickEnter,
+    TickExit,
+    SleepEnter,
+    SleepExit,
+}
+
+#[derive(Clone, Copy)]
+struct Mark {
+    at_ns: u128,
+    phase: Phase,
+    call: u8,
+    detail: u8,
+}
+
+struct Trace {
+    origin: Instant,
+    marks: Box<[Option<Mark>]>,
+    used: usize,
+    lost: u64,
+}
+
+impl Trace {
+    fn new(origin: Instant) -> Self {
+        Self {
+            origin,
+            marks: vec![None; PHASE_RECORDS].into_boxed_slice(),
+            used: 0,
+            lost: 0,
+        }
+    }
+
+    fn push(&mut self, phase: Phase, call: u8, detail: u8) {
+        let at_ns = self.origin.elapsed().as_nanos();
+        if let Some(slot) = self.marks.get_mut(self.used) {
+            *slot = Some(Mark {
+                at_ns,
+                phase,
+                call,
+                detail,
+            });
+            self.used += 1;
+        } else {
+            self.lost = self.lost.saturating_add(1);
+        }
+    }
+
+    fn dump(&self, lane: &str) {
+        eprintln!(
+            "LIGHT_PHASE lane={lane} capacity={} used={} lost={}",
+            self.marks.len(),
+            self.used,
+            self.lost
+        );
+        for mark in self.marks[..self.used].iter().flatten() {
+            eprintln!(
+                "LIGHT_PHASE lane={lane} ns={} phase={:?} call={} detail={}",
+                mark.at_ns, mark.phase, mark.call, mark.detail
+            );
+        }
+    }
+}
+
+struct ObservedLight<'a> {
+    inner: BusLight,
+    trace: &'a mut Trace,
+    call: u8,
+}
+
+impl lamp_actions::light::Light for ObservedLight<'_> {
+    fn there(&mut self) -> bool {
+        self.trace.push(Phase::ThereEnter, self.call, 0);
+        let value = self.inner.there();
+        self.trace
+            .push(Phase::ThereExit, self.call, u8::from(value));
+        value
+    }
+
+    fn shown(&mut self) -> Option<lamp_msgs::Light> {
+        self.trace.push(Phase::ShownEnter, self.call, 0);
+        let value = self.inner.shown();
+        self.trace
+            .push(Phase::ShownExit, self.call, u8::from(value.is_some()));
+        value
+    }
+
+    fn ask(&mut self, light: &lamp_msgs::Light) -> bool {
+        self.trace.push(Phase::AskEnter, self.call, 0);
+        let value = self.inner.ask(light);
+        self.trace.push(Phase::AskExit, self.call, u8::from(value));
+        value
+    }
+
+    fn covered(&mut self) -> bool {
+        self.trace.push(Phase::CoveredEnter, self.call, 0);
+        let value = self.inner.covered();
+        self.trace
+            .push(Phase::CoveredExit, self.call, u8::from(value));
+        value
+    }
+}
+
+#[derive(Clone, Copy)]
+struct Sample {
+    started_ns: u128,
+    elapsed_ns: u128,
+    done: bool,
+}
